const citizenship = prompt('Какое у вас гражданство?', 'РФ');
const otherDebts = parseInt(prompt('Введите общую сумму задолженности перед другими финансовыми предприятиями', '0'), 10);
const age = parseInt(prompt('Сколько вам полных лет?'), 10);
const ok = (citizenship === 'РФ' || citizenship === 'Россия') && !otherDebts && age > 21;

console.log(ok ? 'Кредит одобрен' : 'Извините');
